namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = new();
    public List<string> Steps { get; set; } = new();
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly Lock _lock = new();
    private int _nextId;

    public RecipeService()
    {
        _recipes = new List<Recipe>
        {
            new Recipe
            {
                Id = 1, Title = "Fluffy Pancakes", Category = "Breakfast",
                Ingredients = new List<string> { "2 cups flour", "2 eggs", "1 cup milk", "2 tbsp sugar", "1 tsp baking powder" },
                Steps = new List<string> { "Mix dry ingredients.", "Whisk eggs and milk together.", "Combine wet and dry ingredients.", "Cook on a hot griddle until golden." },
                AverageRating = 4.5, RatingCount = 10
            },
            new Recipe
            {
                Id = 2, Title = "Avocado Toast", Category = "Breakfast",
                Ingredients = new List<string> { "2 slices sourdough bread", "1 ripe avocado", "Salt and pepper", "Red pepper flakes", "Lemon juice" },
                Steps = new List<string> { "Toast the bread.", "Mash the avocado with lemon juice, salt, and pepper.", "Spread on toast and sprinkle with red pepper flakes." },
                AverageRating = 4.0, RatingCount = 6
            },
            new Recipe
            {
                Id = 3, Title = "Spaghetti Bolognese", Category = "Dinner",
                Ingredients = new List<string> { "400g spaghetti", "500g ground beef", "1 can crushed tomatoes", "1 onion", "3 cloves garlic", "Olive oil", "Salt and pepper" },
                Steps = new List<string> { "Cook spaghetti according to package directions.", "Sauté onion and garlic in olive oil.", "Add ground beef and brown.", "Stir in tomatoes, season, and simmer 20 minutes.", "Serve sauce over spaghetti." },
                AverageRating = 4.8, RatingCount = 15
            },
            new Recipe
            {
                Id = 4, Title = "Chicken Stir-Fry", Category = "Dinner",
                Ingredients = new List<string> { "2 chicken breasts", "1 bell pepper", "1 cup broccoli", "3 tbsp soy sauce", "1 tbsp sesame oil", "Rice for serving" },
                Steps = new List<string> { "Slice chicken and vegetables.", "Heat sesame oil in a wok.", "Cook chicken until done, then remove.", "Stir-fry vegetables until tender-crisp.", "Return chicken, add soy sauce, and toss.", "Serve over rice." },
                AverageRating = 4.3, RatingCount = 8
            },
            new Recipe
            {
                Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts",
                Ingredients = new List<string> { "200g dark chocolate", "100g butter", "2 eggs", "2 egg yolks", "50g sugar", "1 tbsp flour" },
                Steps = new List<string> { "Preheat oven to 220°C.", "Melt chocolate and butter together.", "Whisk eggs, yolks, and sugar.", "Fold chocolate mixture into eggs, then fold in flour.", "Pour into greased ramekins and bake 12 minutes.", "Invert onto plates and serve immediately." },
                AverageRating = 4.9, RatingCount = 20
            },
            new Recipe
            {
                Id = 6, Title = "Strawberry Cheesecake", Category = "Desserts",
                Ingredients = new List<string> { "200g graham crackers", "100g melted butter", "500g cream cheese", "100g sugar", "2 eggs", "1 tsp vanilla", "Fresh strawberries" },
                Steps = new List<string> { "Crush crackers and mix with melted butter for the crust.", "Press into a springform pan and chill.", "Beat cream cheese, sugar, eggs, and vanilla until smooth.", "Pour over crust and bake at 160°C for 50 minutes.", "Cool completely, then top with fresh strawberries." },
                AverageRating = 4.7, RatingCount = 12
            }
        };
        _nextId = _recipes.Max(r => r.Id) + 1;
    }

    public List<string> GetCategories()
    {
        lock (_lock)
        {
            return _recipes.Select(r => r.Category).Distinct().ToList();
        }
    }

    public List<Recipe> GetRecipesByCategory(string category)
    {
        lock (_lock)
        {
            return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
        }
    }

    public Recipe? GetRecipeById(int id)
    {
        lock (_lock)
        {
            return _recipes.FirstOrDefault(r => r.Id == id);
        }
    }

    public void AddRating(int recipeId, int stars)
    {
        lock (_lock)
        {
            var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
            if (recipe is not null && stars >= 1 && stars <= 5)
            {
                var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
                recipe.RatingCount++;
                recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
            }
        }
    }

    public void SubmitRecipe(Recipe recipe)
    {
        lock (_lock)
        {
            recipe.Id = _nextId++;
            _recipes.Add(recipe);
        }
    }
}

@rendermode InteractiveServer
@using RecipeShare.Services
@inject RecipeService RecipeService

<div class="star-rating">
    <div class="stars">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="star @(star <= Math.Round(_averageRating) ? "filled" : "")"
                  @onclick="() => Rate(star)">
                @(star <= Math.Round(_averageRating) ? "★" : "☆")
            </span>
        }
    </div>
    <span class="rating-info">@_averageRating.ToString("0.0") / 5 (@_ratingCount ratings)</span>
    @if (_justRated)
    {
        <span class="rating-thanks">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double InitialRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private double _averageRating;
    private int _ratingCount;
    private bool _justRated;

    protected override void OnParametersSet()
    {
        _averageRating = InitialRating;
        _ratingCount = RatingCount;
    }

    private void Rate(int stars)
    {
        RecipeService.AddRating(RecipeId, stars);
        var updated = RecipeService.GetRecipeById(RecipeId);
        if (updated is not null)
        {
            _averageRating = updated.AverageRating;
            _ratingCount = updated.RatingCount;
        }
        _justRated = true;
    }
}

.star-rating {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    flex-wrap: wrap;
    margin: 1rem 0;
}

.stars {
    display: flex;
    gap: 0.15rem;
}

.star {
    font-size: 1.8rem;
    cursor: pointer;
    color: #ccc;
    transition: color 0.15s;
    user-select: none;
}

.star.filled {
    color: #f5a623;
}

.star:hover {
    color: #f5a623;
}

.rating-info {
    font-size: 0.95rem;
    color: #666;
}

.rating-thanks {
    font-size: 0.85rem;
    color: #28a745;
    font-weight: 500;
}

@page "/recipes"
@page "/recipes/{Category}"
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>@(Category is not null ? $"{Category} Recipes" : "Browse Recipes") - RecipeShare</PageTitle>

@if (Category is null)
{
    <h1>Browse Recipes</h1>
    <p>Choose a category to explore recipes:</p>
    <div class="category-list">
        @foreach (var cat in RecipeService.GetCategories())
        {
            <a href="recipes/@cat" class="category-card">
                <h3>@cat</h3>
            </a>
        }
    </div>
}
else
{
    <h1>@Category Recipes</h1>
    <a href="recipes">&larr; All Categories</a>
    <div class="recipe-list">
        @foreach (var recipe in RecipeService.GetRecipesByCategory(Category))
        {
            <a href="recipe/@recipe.Id" class="recipe-card">
                <h3>@recipe.Title</h3>
                <p>⭐ @recipe.AverageRating.ToString("0.0") (@recipe.RatingCount ratings)</p>
            </a>
        }
    </div>
}

@code {
    [Parameter] public string? Category { get; set; }
}

@page "/recipe/{Id:int}"
@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService RecipeService

@if (_recipe is null)
{
    <PageTitle>Recipe Not Found - RecipeShare</PageTitle>
    <h1>Recipe not found</h1>
    <p>The recipe you're looking for doesn't exist.</p>
}
else
{
    <PageTitle>@_recipe.Title - RecipeShare</PageTitle>
    <h1>@_recipe.Title</h1>
    <p><a href="recipes/@_recipe.Category">&larr; Back to @_recipe.Category</a></p>

    <h2>Ingredients</h2>
    <ul>
        @foreach (var ingredient in _recipe.Ingredients)
        {
            <li>@ingredient</li>
        }
    </ul>

    <h2>Steps</h2>
    <ol>
        @foreach (var step in _recipe.Steps)
        {
            <li>@step</li>
        }
    </ol>

    <h2>Rating</h2>
    <StarRating RecipeId="@_recipe.Id"
                InitialRating="@_recipe.AverageRating"
                RatingCount="@_recipe.RatingCount" />
}

@code {
    [Parameter] public int Id { get; set; }
    private Recipe? _recipe;

    protected override void OnInitialized()
    {
        _recipe = RecipeService.GetRecipeById(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>

@if (_submitted)
{
    <div class="alert alert-success">
        <strong>Success!</strong> Your recipe "<strong>@_title</strong>" has been submitted.
    </div>
    <button class="btn btn-primary" @onclick="Reset">Submit Another</button>
}
else
{
    <div class="form-group mb-3">
        <label for="title">Title</label>
        <input id="title" class="form-control" @bind="_title" placeholder="Recipe title" />
    </div>

    <div class="form-group mb-3">
        <label for="category">Category</label>
        <select id="category" class="form-control" @bind="_category">
            <option value="">-- Select a category --</option>
            <option value="Breakfast">Breakfast</option>
            <option value="Dinner">Dinner</option>
            <option value="Desserts">Desserts</option>
        </select>
    </div>

    <div class="form-group mb-3">
        <label for="ingredients">Ingredients (one per line)</label>
        <textarea id="ingredients" class="form-control" rows="5" @bind="_ingredientsText" placeholder="1 cup flour&#10;2 eggs&#10;..."></textarea>
    </div>

    <div class="form-group mb-3">
        <label for="steps">Steps (one per line)</label>
        <textarea id="steps" class="form-control" rows="5" @bind="_stepsText" placeholder="Preheat oven to 350°F.&#10;Mix ingredients.&#10;..."></textarea>
    </div>

    <button class="btn btn-primary" @onclick="HandleSubmit">Submit Recipe</button>
}

@code {
    private string _title = string.Empty;
    private string _category = string.Empty;
    private string _ingredientsText = string.Empty;
    private string _stepsText = string.Empty;
    private bool _submitted;

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(_title) || string.IsNullOrWhiteSpace(_category))
            return;

        var recipe = new Recipe
        {
            Title = _title.Trim(),
            Category = _category,
            Ingredients = _ingredientsText
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
            Steps = _stepsText
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList()
        };

        RecipeService.SubmitRecipe(recipe);
        _submitted = true;
    }

    private void Reset()
    {
        _title = string.Empty;
        _category = string.Empty;
        _ingredientsText = string.Empty;
        _stepsText = string.Empty;
        _submitted = false;
    }
}

