@using RecipeShare.Services
@inject RecipeService RecipeService

<div class="star-rating">
    <div class="stars">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="star @(star <= Math.Round(_averageRating) ? "filled" : "")"
                  @onclick="() => Rate(star)">
                @(star <= Math.Round(_averageRating) ? "★" : "☆")
            </span>
        }
    </div>
    <span class="rating-info">@_averageRating.ToString("0.0") / 5 (@_ratingCount ratings)</span>
    @if (_justRated)
    {
        <span class="rating-thanks">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double InitialRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private double _averageRating;
    private int _ratingCount;
    private bool _justRated;

    protected override void OnParametersSet()
    {
        _averageRating = InitialRating;
        _ratingCount = RatingCount;
    }

    private void Rate(int stars)
    {
        RecipeService.AddRating(RecipeId, stars);
        var updated = RecipeService.GetRecipeById(RecipeId);
        if (updated is not null)
        {
            _averageRating = updated.AverageRating;
            _ratingCount = updated.RatingCount;
        }
        _justRated = true;
    }
}

