 @page "/recipes"
 @page "/recipes/{Category}"
 @using RecipeShare.Services
 @inject RecipeService RecipeService

 <PageTitle>@(Category is not null ? $"{Category} Recipes" : "Browse Recipes") - RecipeShare</PageTitle>

 @if (Category is null)
 {
     <h1>Browse Recipes</h1>
     <p>Choose a category to explore recipes:</p>
     <div class="category-list">
         @foreach (var cat in RecipeService.GetCategories())
         {
             <a href="recipes/@cat" class="category-card">
                 <h3>@cat</h3>
             </a>
         }
     </div>
 }
 else
 {
     <h1>@Category Recipes</h1>
     <a href="recipes">&larr; All Categories</a>
     <div class="recipe-list">
         @foreach (var recipe in RecipeService.GetRecipesByCategory(Category))
         {
             <a href="recipe/@recipe.Id" class="recipe-card">
                 <h3>@recipe.Title</h3>
                 <p>⭐ @recipe.AverageRating.ToString("0.0") (@recipe.RatingCount ratings)</p>
             </a>
         }
     </div>
 }

 @code {
     [Parameter] public string? Category { get; set; }
 }

