 @page "/submit"
 @rendermode InteractiveServer
 @using RecipeShare.Models
 @using RecipeShare.Services
 @inject RecipeService RecipeService

 <PageTitle>Submit a Recipe - RecipeShare</PageTitle>

 <h1>Submit a Recipe</h1>

 @if (_submitted)
 {
     <div class="alert alert-success">
         <strong>Success!</strong> Your recipe "<strong>@_title</strong>" has been submitted.
     </div>
     <button class="btn btn-primary" @onclick="Reset">Submit Another</button>
 }
 else
 {
     <div class="form-group mb-3">
         <label for="title">Title</label>
         <input id="title" class="form-control" @bind="_title" placeholder="Recipe title" />
     </div>

     <div class="form-group mb-3">
         <label for="category">Category</label>
         <select id="category" class="form-control" @bind="_category">
             <option value="">-- Select a category --</option>
             <option value="Breakfast">Breakfast</option>
             <option value="Dinner">Dinner</option>
             <option value="Desserts">Desserts</option>
         </select>
     </div>

     <div class="form-group mb-3">
         <label for="ingredients">Ingredients (one per line)</label>
         <textarea id="ingredients" class="form-control" rows="5" @bind="_ingredientsText" placeholder="1 cup flour&#10;2 eggs&#10;..."></textarea>
     </div>

     <div class="form-group mb-3">
         <label for="steps">Steps (one per line)</label>
         <textarea id="steps" class="form-control" rows="5" @bind="_stepsText" placeholder="Preheat oven to 350°F.&#10;Mix ingredients.&#10;..."></textarea>
     </div>

     <button class="btn btn-primary" @onclick="HandleSubmit">Submit Recipe</button>
 }

 @code {
     private string _title = string.Empty;
     private string _category = string.Empty;
     private string _ingredientsText = string.Empty;
     private string _stepsText = string.Empty;
     private bool _submitted;

     private void HandleSubmit()
     {
         if (string.IsNullOrWhiteSpace(_title) || string.IsNullOrWhiteSpace(_category))
             return;

         var recipe = new Recipe
         {
             Title = _title.Trim(),
             Category = _category,
             Ingredients = _ingredientsText
                 .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                 .ToList(),
             Steps = _stepsText
                 .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                 .ToList()
         };

         RecipeService.SubmitRecipe(recipe);
         _submitted = true;
     }

     private void Reset()
     {
         _title = string.Empty;
         _category = string.Empty;
         _ingredientsText = string.Empty;
         _stepsText = string.Empty;
         _submitted = false;
     }
 }

